import ast,hashlib,importlib.util,json
from pathlib import Path
root=Path('/workspace');r=json.loads((root/'runtime_contract.json').read_text());p=json.loads((root/'proposal.json').read_text())
print('torch available:',importlib.util.find_spec('torch') is not None)
print('jsonschema available:',importlib.util.find_spec('jsonschema') is not None)
if importlib.util.find_spec('jsonschema'):
 import jsonschema
 jsonschema.Draft202012Validator(r['study_schema']).validate(p['study'])
 print('Prospective study schema: valid')
else:
 def check(x,s,path='"'$'"'):
  t=s.get('type')
  if t=='object':
   assert isinstance(x,dict),path
   assert set(s.get('required',[]))<=set(x),path
   if s.get('additionalProperties') is False:assert set(x)<=set(s.get('properties',{})),path
   for k,v in x.items():
    if k in s.get('properties',{}):check(v,s['properties'][k],path+'.'+k)
  elif t=='array':
   assert isinstance(x,list) and len(x)>=s.get('minItems',0),path
   for i,v in enumerate(x):check(v,s['items'],path+str(i))
  elif t=='string':assert isinstance(x,str) and len(x)>=s.get('minLength',0),path
  if 'enum' in s:assert x in s['enum'],path
